UPDATE "research_group_translation" SET "futureWork" = '<ul>' || replace(replace(replace(replace("futureWork", '</p>' || char(10) || char(10), '</p>'), '<p>● ', '<li><p>'), '</p>', '</p></li>'), ' .</p>', '.</p>') || '</ul>' WHERE "futureWork" LIKE '<p>● %</p>' AND instr(replace("futureWork", '<p>● ', ''), '<p>') = 0 AND instr(replace("futureWork", '</p>' || char(10) || char(10), '</p>'), char(10)) = 0;
